			const match = /^nodejs\s+(\S+)/.exec(line.trim());
			if (match === null) continue;
			const text = match[1] as string;
			readings.push(
				Object.freeze({
					source: '.tool-versions#nodejs',
					text,
					majors: nodeMajorsOfDeclaration(text),
				}),
