describe('operator run — the first refusing stage settles the run', () => {
	/**
	 * The work area is a copy with no Git metadata, so admission refuses for
	 * the revision it cannot read. Admission is ordered before the toolchain
	 * cell and before the plan, so it is the stage that decides — the frozen
	 * adapter's own refusal for this tree is never reached, and the record says
	 * so rather than reporting a plan nobody composed.
	 */
	it('exits 2 with the refusing stage’s own string, and records the rest as not run', async () => {
		const lane = await laneDirectory();
		const { record, exitCode } = await runPipeline([MYCRYPTO, '--out', lane]);
		expect(exitCode).toBe(EXIT_REFUSAL);
		expect(record.exitCode).toBe(EXIT_REFUSAL);
